<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --surface: #121a2f;
      --surface-2: #18233d;
      --border: #30405f;
      --text: #edf2ff;
      --muted: #b8c3de;
      --accent: #7c9cff;
      --accent-strong: #9eb4ff;
      --focus: #f6c177;
      --success: #68d391;
    }

    * {
      box-sizing: border-box;
    }

    html {
      background: var(--bg);
      color: var(--text);
    }

    body {
      margin: 0;
      font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      min-height: 100vh;
      background:
        radial-gradient(circle at top, #18264a 0, transparent 38%),
        linear-gradient(180deg, #0b1020 0%, #0f1628 100%);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-200%);
      background: var(--focus);
      color: #111827;
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      text-decoration: none;
      font-weight: 700;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--text);
      outline-offset: 2px;
    }

    main {
      width: min(900px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 5rem 0 3rem;
    }

    .quiz-shell {
      background: linear-gradient(180deg, rgba(24, 35, 61, 0.96), rgba(12, 18, 33, 0.96));
      border: 1px solid var(--border);
      border-radius: 1.25rem;
      box-shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
      padding: 1.5rem;
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 1.5rem;
      color: var(--muted);
      max-width: 65ch;
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 1rem;
      padding: 1rem;
    }

    fieldset {
      border: 0;
      margin: 0;
      padding: 0;
      min-width: 0;
    }

    legend {
      font-size: 1.1rem;
      font-weight: 700;
      margin-bottom: 0.5rem;
      padding: 0;
    }

    .help-text {
      margin: 0 0 0.75rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      gap: 0.75rem;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      padding: 0.85rem 0.9rem;
      border: 1px solid var(--border);
      border-radius: 0.85rem;
      background: var(--surface-2);
      transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
