      appearance: none;
      border: 1px solid transparent;
      background: linear-gradient(180deg, #8ca7ff, #6f8df5);
      color: #08101f;
      font: inherit;
      font-weight: 700;
      padding: 0.9rem 1.3rem;
      border-radius: 0.9rem;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(111, 141, 245, 0.28);
    }

    button:hover {
      background: linear-gradient(180deg, #9ab0ff, #7a96ff);
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 600;
      overflow-wrap: anywhere;
    }

    .summary {
      margin-top: 1rem;
      padding: 1rem;
      border: 1px solid var(--border);
      border-radius: 0.9rem;
      background: rgba(14, 22, 41, 0.85);
      color: var(--muted);
      white-space: pre-line;
    }

    .summary strong {
      color: var(--text);
    }

    @media (max-width: 640px) {
      main {
        width: min(100% - 1rem, 900px);
        padding-top: 4.5rem;
      }

      .quiz-shell {
        padding: 1rem;
        border-radius: 1rem;
      }

      .actions {
        align-items: stretch;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --border: ButtonBorder;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: ButtonText;
        --accent-strong: ButtonText;
        --focus: Highlight;
        --success: CanvasText;
      }

      .skip-link,
      .choice,
      button,
      .summary,
      .quiz-shell {
        forced-color-adjust: auto;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>
  <main id="main">
    <section class="quiz-shell" aria-labelledby="quiz-title">
      <h1 id="quiz-title">Computer Languages Quiz</h1>
      <p class="intro">Select every answer that applies for each question. Each question uses checkboxes so you can choose multiple answers.</p>

      <form id="quiz-form">
        <div class="form-field">
          <fieldset>
            <legend>1. Which of these are programming languages?</legend>
            <p class="help-text" id="q1-help">Choose any that you recognize as languages used to write software.</p>
            <div class="choices">
              <label class="choice"><input type="checkbox" name="q1" value="JavaScript" /><span>JavaScript</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="HTML" /><span>HTML</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="Python" /><span>Python</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="CSS" /><span>CSS</span></label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset aria-describedby="q1-help">
            <legend>2. Which languages are commonly used on the web?</legend>
            <div class="choices">
              <label class="choice"><input type="checkbox" name="q2" value="JavaScript" /><span>JavaScript</span></label>
              <label class="choice"><input type="checkbox" name="q2" value="TypeScript" /><span>TypeScript</span></label>
              <label class="choice"><input type="checkbox" name="q2" value="Ruby" /><span>Ruby</span></label>
              <label class="choice"><input type="checkbox" name="q2" value="SQL" /><span>SQL</span></label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which of these are compiled languages?</legend>
            <div class="choices">
              <label class="choice"><input type="checkbox" name="q3" value="C" /><span>C</span></label>
              <label class="choice"><input type="checkbox" name="q3" value="Go" /><span>Go</span></label>
              <label class="choice"><input type="checkbox" name="q3" value="Swift" /><span>Swift</span></label>
              <label class="choice"><input type="checkbox" name="q3" value="JavaScript" /><span>JavaScript</span></label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit quiz</button>
          <div class="status" id="status" aria-live="polite"></div>
        </div>

        <div class="summary" id="summary" hidden></div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('quiz-form');
    const status = document.getElementById('status');
    const summary = document.getElementById('summary');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const answers = [1, 2, 3].map((questionNumber) => {
        const values = [...form.querySelectorAll(`input[name="q${questionNumber}"]:checked`)].map((input) => input.value);
        return `Question ${questionNumber}: ${values.length ? values.join(', ') : 'No answers selected'}`;
      });

      status.textContent = 'Quiz submitted.';
      summary.hidden = false;
      summary.textContent = `Your selections:\n${answers.join('\n')}`;
    });
  </script>
</body>
</html>
